package br.com.andre22bodybuilder.meufinanceiro;
import android.app.*;import android.os.*;import android.graphics.Color;import android.net.Uri;import android.content.*;import android.appwidget.*;import android.webkit.*;import android.widget.*;
public class QuickEntryActivity extends Activity{
 EditText d,v;Spinner c;String type;Button save;WebView web;
 public void onCreate(Bundle b){super.onCreate(b);type=getIntent().getStringExtra("type");if(type==null)type="in";LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(40,28,40,28);l.setBackgroundColor(Color.rgb(16,21,18));TextView t=new TextView(this);t.setText(type.equals("in")?"Nova entrada":"Nova saída");t.setTextSize(22);t.setTextColor(type.equals("in")?Color.rgb(53,245,106):Color.rgb(255,83,98));l.addView(t);d=new EditText(this);d.setHint("Descrição");d.setTextColor(Color.WHITE);d.setHintTextColor(Color.GRAY);l.addView(d);v=new EditText(this);v.setHint("Valor");v.setInputType(2|8192);v.setTextColor(Color.WHITE);v.setHintTextColor(Color.GRAY);l.addView(v);c=new Spinner(this);String[] cs={"Uber","Consultoria","C+A","Combustível","Alimentação","Manutenção","Contas","Compras","Produtos","Outros"};c.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,cs));l.addView(c);save=new Button(this);save.setText("Salvar");save.setOnClickListener(x->save());l.addView(save);web=new WebView(this);web.getSettings().setJavaScriptEnabled(true);web.setVisibility(android.view.View.GONE);web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView w,String url){if(url.startsWith("widget-saved:")){Toast.makeText(QuickEntryActivity.this,"Lançamento salvo",Toast.LENGTH_SHORT).show();AppWidgetManager am=AppWidgetManager.getInstance(QuickEntryActivity.this);int[] ids=am.getAppWidgetIds(new ComponentName(QuickEntryActivity.this,FinanceWidget.class));new FinanceWidget().onUpdate(QuickEntryActivity.this,am,ids);finish();return true;}return false;}});l.addView(web,new LinearLayout.LayoutParams(1,1));setContentView(l);}
 void save(){String ds=d.getText().toString().trim(),vs=v.getText().toString().trim();if(ds.isEmpty()||vs.isEmpty()){Toast.makeText(this,"Preencha descrição e valor",Toast.LENGTH_SHORT).show();return;}save.setEnabled(false);String url="https://andresalles274-creator.github.io/meu-financeiro/app/?widgetSave=1&type="+Uri.encode(type)+"&desc="+Uri.encode(ds)+"&value="+Uri.encode(vs)+"&cat="+Uri.encode(c.getSelectedItem().toString());web.loadUrl(url);}
}